def evaluate(clause):
    failed = [name for name, check in RULES if not check(clause)]
    return len(RULES) - len(failed), failed

def refine(brief, max_rounds=3):
    draft = ask("Draft an NDA confidentiality clause.\n" + brief)
    best, best_score = draft, -1
    for _ in range(max_rounds):
        score, failed = evaluate(draft)             # external feedback
        if score > best_score:
            best, best_score = draft, score
        if not failed:
            break                                   # every rule passes
        critique = "Fix these failed rules: " + "; ".join(failed)
        draft = ask(f"{brief}\n\nDraft:\n{draft}\n\n{critique}\nReturn only the revised clause.")
    else:
        score, _ = evaluate(draft)                  # score the last revision too
        if score > best_score:
            best, best_score = draft, score
    return best, best_score

import anthropic

claude = anthropic.Anthropic()

def review(case: str, hard: bool):
    kwargs = {"max_tokens": 20000}
    if hard:                                           # route by difficulty
        kwargs["thinking"] = {"type": "enabled", "budget_tokens": 16000}
    r = claude.messages.create(model="claude-sonnet-4-5",   # use your current model
        messages=[{"role": "user", "content": case}], **kwargs)
    answer = next(b.text for b in r.content if b.type == "text")
    return answer, r.usage.output_tokens               # includes thinking tokens

